inlineStyles.content:
/* Layout: full-bleed hero (light + charcoal dark mode) — greeting + flip-calendar skills top-left, card bottom-left, cut-out portrait anchored right on the status hairline. */
:root{
  --background:#E8E4E0; --foreground:#1A1818; --ink:#1A1818;
  --muted:#857878; --subtle:#B5A8A8; --line:#D5CDCA;
  --surface:#DED8D4; --surface-2:#D3CBC8;
  --accent:#6B5C5C; --accent-from:#C4B0B0; --accent-to:#6B5C5C;
  --hero-from:#EEEAE6; --hero-mid:#E8E4E0; --hero-to:#D8CDCA;
  --radius-pill:9999px; --radius-card:2rem; --radius-card-sm:1.25rem; --radius-control:.875rem;
  --text-watermark:13rem; --container-shell:88rem;
  --font:'Onest',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;
  --e-line:cubic-bezier(.215,.61,.355,1);
  --e-spring:cubic-bezier(.22,1,.36,1);
  --e-soft:cubic-bezier(.16,1,.3,1);
  --e-snap:cubic-bezier(.2,.8,.2,1);
  --bar-h:3.5rem;
  --gut-lg:5.5rem;   /* one side margin for nav, headline, chips and portrait */
  /* mode-dependent tokens (light) */
  --fg-rgb:26,24,24;
  --chip-bg:rgba(242,238,235,.5); --chip-bg-h:rgba(242,238,235,.85); --chip-line:rgba(196,176,176,.45);
  --btn-bg:#1A1818; --btn-fg:#E8E4E0; --btn-badge-bg:#E8E4E0; --btn-badge-fg:#1A1818;
  --outline-h:rgba(196,176,176,.18);
  --vig:rgba(240,236,232,.35);
  --panel:#F0ECE9; --field:rgba(196,176,176,.12); --scrim:rgba(var(--fg-rgb),.3);
  --cord-shadow:.2;
  color-scheme:light;
}
/* dark mode: charcoal, a step above pure black */
html[data-mode="dark"]{
  --background:#1A1818; --foreground:#E8E4E0; --fg-rgb:232,228,224;
  --line:rgba(196,176,176,.16); --surface:#252121; --surface-2:#302A2A;
  --chip-bg:rgba(196,176,176,.06); --chip-bg-h:rgba(196,176,176,.12); --chip-line:rgba(196,176,176,.16);
  --btn-bg:#E8E4E0; --btn-fg:#1A1818; --btn-badge-bg:#1A1818; --btn-badge-fg:#E8E4E0;
  --outline-h:rgba(196,176,176,.08);
  --vig:rgba(0,0,0,.22);
  --panel:#221F1F; --field:rgba(196,176,176,.06); --scrim:rgba(0,0,0,.55);
  --cord-shadow:.55;
  color-scheme:dark;
}
/* mode switch: one GPU crossfade of the whole page (View Transitions) instead of
   hundreds of per-element colour transitions running out of step */
::view-transition-old(root),::view-transition-new(root){animation-duration:.5s;animation-timing-function:cubic-bezier(.4,0,.2,1)}
.cord{view-transition-name:cord}
#cal{view-transition-name:cal}
::view-transition-old(cal){display:none}
::view-transition-new(cal){animation:none}
::view-transition-old(cord){display:none}
::view-transition-new(cord){animation:none}
*{box-sizing:border-box;margin:0;padding:0}
html{overscroll-behavior-y:none;scrollbar-width:none;font-size:16px;-webkit-font-smoothing:antialiased;background:#1A1818;overflow-x:clip}
html[data-mode="dark"]{background:#0F0E0E}
html::-webkit-scrollbar,body::-webkit-scrollbar{display:none;width:0;height:0}
body{background:var(--background);color:var(--foreground);font-family:var(--font);overflow-x:clip}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
ul{list-style:none}
img{display:block;max-width:none}
svg{display:block;width:1em;height:1em;flex:none}
[hidden]{display:none!important}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.tnum{font-variant-numeric:tabular-nums}

/* ---------- adaptive rem grid ---------- */
@media (max-width:1920px){html{font-size:.833333vw}}
@media (max-width:1440px){html{font-size:1.111111vw}}
@media (max-width:1024px){html{font-size:1.5625vw}}
@media (max-width:640px){html{font-size:4.444444vw}}

.shell{max-width:var(--container-shell);margin-inline:auto;padding-inline:1.25rem;width:100%}
@media (min-width:640px){.shell{padding-inline:2rem}}
@media (min-width:1024px){.shell{padding-inline:var(--gut-lg)}}

/* ---------- skip link ---------- */
.skip{position:absolute;left:-9999px;top:auto}
.skip:focus{position:fixed;left:1rem;top:1rem;z-index:60;min-height:44px;display:inline-flex;align-items:center;border-radius:var(--radius-control);background:var(--ink);padding:.5rem 1rem;font-size:.875rem;color:#fff}

/* ---------- reveal system (plays once body.ready is set) ---------- */
.rv{opacity:0;transform:var(--from,translateY(10px));transition:opacity .8s var(--ease,var(--e-soft)) var(--d,0ms),transform .8s var(--ease,var(--e-soft)) var(--d,0ms)}
body.ready .rv{opacity:var(--to-o,1);transform:none}
.line{display:block;overflow:hidden;padding-bottom:.06em;margin-bottom:-.06em}
.line>span{display:block;transform:translateY(100%);opacity:0;transition:transform .9s var(--e-line) var(--d,0ms),opacity .9s var(--e-line) var(--d,0ms)}
body.ready .line>span{transform:none;opacity:1}

/* ---------- loader: the doors' colours stack up, one per discipline, then slides away to open the page ---------- */
.loader{position:fixed;inset:0;z-index:120;overflow:hidden;color:#E8E4E0;--p:0;font-family:'Onest',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif}
.ld__bg{position:absolute;inset:0;background:radial-gradient(38% 55% at 0% 72%,rgba(164,85,44,.26),transparent 70%),radial-gradient(40% 58% at 100% 70%,rgba(196,176,176,.16),transparent 72%),
  radial-gradient(70% 60% at 50% 0%,rgba(107,92,92,.3),transparent 70%),#0D0C0C;transition:transform .85s cubic-bezier(.76,0,.24,1)}
.loader.out .ld__bg{transform:translateY(-100%)}
.ld__stack{--w:min(76vw,26rem);--h:calc(var(--w) * .27);--step:calc(var(--h) * .6);position:absolute;left:50%;top:47%;width:var(--w);height:calc(var(--h) + 5 * var(--step));translate:-50% -50%}
@media (max-width:639.98px){.ld__stack{--w:min(78vw,20rem)}}
.ld__pill{position:absolute;left:0;top:calc(var(--k) * var(--step));width:100%;height:var(--h);border-radius:999px;z-index:var(--k);
  display:flex;align-items:flex-start;padding:calc(var(--h) * .2) 0 0 calc(var(--w) * .16);font-size:max(11px,calc(var(--w) * .036));font-weight:500;letter-spacing:.02em;
  background:var(--c);
  background:linear-gradient(180deg,color-mix(in srgb,var(--c) 88%,#fff) 0%,var(--c) 22%,var(--c) 70%,color-mix(in srgb,var(--c) 82%,#000) 100%);color:var(--t);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.14),0 -1px 0 rgba(0,0,0,.25),0 calc(var(--h) * -.18) calc(var(--h) * .35) calc(var(--h) * -.12) rgba(0,0,0,.55);
  opacity:0;transform:translateY(-1.6rem) scale(.96);transition:opacity .45s ease,transform .75s cubic-bezier(.16,1,.3,1)}
.ld__pill.on{opacity:1;transform:none}
.ld__pill span{opacity:.82}
.loader.out .ld__pill{transition:transform .8s cubic-bezier(.7,0,.25,1) calc(var(--k) * 45ms),opacity .5s ease calc(.25s + var(--k) * 45ms);opacity:0;
  transform:translateX(calc(var(--dir) * 115vw)) rotate(calc(var(--dir) * 4deg))}
.ld__hud{position:absolute;inset:0;pointer-events:none;display:flex;flex-direction:column;justify-content:space-between;padding:clamp(1.25rem,4vw,3rem);transition:opacity .35s ease}
.loader.out .ld__hud{opacity:0}
.ld__top{display:flex;justify-content:space-between;align-items:center;font-size:.8125rem;font-weight:500;color:rgba(232,228,224,.7)}
.ld__top b{font-weight:600;color:#E8E4E0}
.ld__bot{display:flex;justify-content:space-between;align-items:flex-end;gap:1.5rem}
.ld__num{font-size:clamp(3.5rem,9vw,7.5rem);font-weight:700;line-height:.85;letter-spacing:-.05em;font-variant-numeric:tabular-nums;color:#E8E4E0}
.ld__num small{display:block;margin-bottom:.9rem;font-family:ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:.6875rem;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:rgba(232,228,224,.62)}
.ld__bar{width:min(30vw,14rem);height:2px;border-radius:2px;background:rgba(232,228,224,.14);overflow:hidden;margin-bottom:.5rem}
.ld__bar i{display:block;height:100%;background:linear-gradient(90deg,#6B5C5C,#C4B0B0,#D6B26E);transform-origin:0 50%;transform:scaleX(var(--p))}
@media (max-width:639.98px){.ld__top span:last-child{display:none}.ld__bar{width:34vw}}
@media (prefers-reduced-motion:reduce){.ld__pill{transform:none;transition:opacity .3s ease}.loader.out .ld__pill{transform:none}.ld__bg{transition:opacity .4s ease}.loader.out .ld__bg{transform:none;opacity:0}}

/* ---------- header ---------- */
.hdr{position:fixed;inset-inline:0;top:0;z-index:50;transition:background .35s ease,box-shadow .35s ease,opacity .35s ease,translate .45s var(--e-soft);--from:translateY(-14px);--d:150ms;--ease:var(--e-spring)}
.hdr.stuck{background:var(--background);box-shadow:0 1px 0 rgba(var(--fg-rgb),.08)}
.hdr.stuck .hdr__in{padding-block:.85rem}
.hdr.away{opacity:0;translate:0 -100%;pointer-events:none}
.hdr__in{transition:padding .35s ease;display:flex;align-items:center;justify-content:space-between;gap:1.5rem;padding-block:1.25rem}
@media (min-width:640px){.hdr__in{padding-block:1.5rem}}
.brand{display:flex;align-items:center;gap:.5rem;font-size:1.375rem;font-weight:600;letter-spacing:-.01em}
.brand svg{font-size:1.5rem;color:var(--accent)}
.hdr nav{flex:1;min-width:0}
.nav{display:none}
@media (min-width:1200px){.nav{display:flex;gap:1.4rem;font-size:1rem;white-space:nowrap}.menu-btn{display:none}}

/* small screens: clock on the left, menu on the right, the pull cord hangs between them */
@media (max-width:1199.98px){.hdr nav{display:none}.hdr__right{flex:1;justify-content:space-between}}

.nav button{display:block}
.nav button>span{display:inline-flex;align-items:center;gap:.25rem;opacity:.8}
.caret{font-size:.75rem;opacity:.6}
.hdr__right{display:flex;align-items:center;gap:.75rem}
.chip{border:1px solid var(--chip-line);background:var(--chip-bg);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);border-radius:var(--radius-control)}
.clock{display:flex;flex:none;white-space:nowrap;align-items:center;gap:.75rem;padding:.6rem .9rem;font-size:.875rem;color:rgba(var(--fg-rgb),.7)}
.clock__ds{display:none;font-weight:500}

@media (max-width:767.98px){.clock{gap:.5rem;padding:.55rem .8rem;font-size:.8125rem}.clock__date,.clock__sep{display:none}.clock .clock__time{min-width:0}}
/* phones and tablets: menu on the left, local time on the right */
@media (max-width:1199.98px){.menu-btn{order:-1}}
.clock__lbl{color:rgba(var(--fg-rgb),.66)}
.clock__time{min-width:4rem;font-weight:500;color:var(--foreground)}
.clock__sep{color:rgba(var(--fg-rgb),.3)}
.clock__date{font-weight:500}
.menu-btn{transition:background .25s}
.menu-btn:hover{background:var(--chip-bg-h)}
.menu-btn>span{display:flex;align-items:center;gap:.5rem;padding:.6rem 1.1rem;font-size:.875rem;font-weight:500;text-transform:uppercase;letter-spacing:.05em}
.menu-btn svg{font-size:1rem}
.menu-btn .word{display:none}
@media (min-width:640px){.menu-btn .word{display:inline}}

/* ---------- hero ---------- */
.hero{position:relative;isolation:isolate;overflow:hidden;border-radius:0 0 var(--radius-card) var(--radius-card);
  background:radial-gradient(120% 90% at 62% 30%,var(--hero-from) 0%,var(--hero-mid) 48%,var(--hero-to) 100%);
  --fig-h:27rem;min-height:100svh;display:flex;flex-direction:column}
.hero__content{flex:1}
@media (min-width:768px) and (max-width:1023.98px){.hero{--fig-h:43rem}}
.hero::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:0;
  background:radial-gradient(120% 90% at 62% 30%,#2A2525 0%,#1F1C1C 48%,#141212 100%)}
html[data-mode="dark"] .hero::before{opacity:1}
.hero__vig{position:absolute;inset:0;z-index:0;pointer-events:none;background:linear-gradient(to bottom,var(--vig),transparent,var(--vig))}

/* the portrait (liquid reveal stage) */
.hero__stage{position:absolute;inset:0;z-index:2;pointer-events:none}
.fig{position:absolute;bottom:var(--bar-h);left:50%;height:var(--fig-h);aspect-ratio:801/1033;
  opacity:0;transition:opacity 1.1s var(--e-soft) 120ms,transform 1.3s var(--e-soft) 120ms;transform:translate(-50%,2.5rem)}
body.ready .fig{opacity:1;transform:translate(-50%,0)}
@media (min-width:1024px){
  .fig{height:min(calc(100% - var(--bar-h) - 6rem),58rem,calc((min(100vw,var(--container-shell)) - 2 * var(--gut-lg)) * .44 * 1033 / 801));left:auto;right:calc(max(0px,(100% - var(--container-shell)) / 2) + var(--gut-lg));transform:translateY(2.5rem)}
  body.ready .fig{transform:none}
}
.fig__wm{position:absolute;left:50%;translate:-50% 0;bottom:42%;white-space:nowrap;pointer-events:none;user-select:none;font-weight:700;line-height:1;letter-spacing:-.02em;color:rgba(255,255,255,.62);font-size:4.25rem}
@media (min-width:640px) and (max-width:1023.98px){.fig__wm{font-size:8rem}}
@media (min-width:1024px){.fig__wm{left:auto;right:-1rem;translate:none;bottom:24%;font-size:11rem}}
.hero__paint{position:absolute;inset:0;width:100%;height:100%;z-index:3;pointer-events:none}
.fig{pointer-events:auto;cursor:pointer}
.hero__content{pointer-events:none}.hero__content a,.hero__content button,.hero__content .cal,.hero__content [data-h]{pointer-events:auto}
/* the ability card: a small tag on the photo, and the card itself in a full-screen layer */
.fig__card{position:absolute;left:8%;bottom:16%;z-index:3;display:inline-flex;align-items:center;gap:.45rem;min-height:44px;padding:0 1rem;border-radius:999px;
  border:1px solid rgba(255,255,255,.22);background:rgba(26,24,24,.72);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);color:#F3EEEC;
  font:600 .8125rem/1 'Onest',ui-sans-serif,system-ui,sans-serif;letter-spacing:.01em;cursor:pointer;box-shadow:0 10px 24px -12px rgba(0,0,0,.6);
  transition:transform .35s cubic-bezier(.16,1,.3,1),background .25s}
@media (max-width:1023.98px){.fig__card{bottom:7%;left:4%}}
.fig:hover .fig__card,.fig__card:focus-visible{transform:translateY(-3px);background:rgba(26,24,24,.88)}
.holo{position:fixed;inset:0;z-index:118;background:#050404;opacity:0;visibility:hidden;transition:opacity .35s ease,visibility 0s linear .35s}
.holo.on{opacity:1;visibility:visible;transition:opacity .35s ease}
/* the card's frame stays invisible until it draws the very same loader, then it simply takes over */
.holo iframe{position:absolute;inset:0;display:block;width:100%;height:100%;border:0;background:#050404;opacity:0;pointer-events:none}
.holo iframe.up{opacity:1;pointer-events:auto}
.holo__ld{position:absolute;inset:0;z-index:1;transition:opacity .45s ease,visibility 0s linear .45s}
.holo__ld.out{opacity:0;visibility:hidden}
.holo__ld.gone{display:none}
.holo.on .cl__card{animation:clIn .6s cubic-bezier(.16,1,.3,1) both}
@keyframes clIn{from{opacity:0;transform:translateY(10px) scale(.96)}}
.cl{position:absolute;inset:0;display:grid;place-content:center;justify-items:center;gap:18px;background:radial-gradient(60% 48% at 50% 46%,#2a2220 0%,#120f0f 58%,#050404 100%);
  font-family:ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;color:#E8E4E0;-webkit-font-smoothing:antialiased}
.cl__name{margin:0;font-size:13px;font-weight:600;line-height:1;letter-spacing:.34em;text-indent:.34em;text-transform:uppercase;color:#E8E4E0}
.cl__line{position:relative;width:clamp(180px,42vw,260px);height:2px;border-radius:2px;background:rgba(232,228,224,.14);overflow:hidden}
.cl__line i{position:absolute;inset:0;border-radius:inherit;background:linear-gradient(90deg,#a98747,#D6B26E 60%,#efdfb2);transform-origin:0 50%;
  transform:scaleX(var(--p,0));transition:transform .45s ease}
.cl__row{display:flex;justify-content:space-between;width:clamp(180px,42vw,260px);margin:0;font:500 10.5px/1 ui-monospace,'SF Mono',Menlo,Consolas,monospace;letter-spacing:.16em;text-transform:uppercase;color:rgba(232,228,224,.6)}
.cl__row b,.cl__row #ld-pct{font-weight:600;letter-spacing:.16em;color:#D6B26E}
@media (prefers-reduced-motion:reduce){.cl__line i{transition:none}}
/* the ability card: the same art the 3D scene used, as layers that part and catch the light */
.holo__lite{position:absolute;inset:0;z-index:2;display:grid;place-content:center;justify-items:center;gap:1.5rem;background:radial-gradient(60% 48% at 50% 46%,#2a2220 0%,#120f0f 58%,#050404 100%);opacity:0;transition:opacity .5s ease}
.holo__lite.in{opacity:1}
.holo__lite .hc{transform:translateY(18px) scale(.96);transition:transform .9s cubic-bezier(.16,1,.3,1)}
.holo__lite.in .hc{transform:none}
.hc{position:relative;width:min(84vw,calc(80svh * .716),34rem);aspect-ratio:1040/1452;padding:0;border:0;background:none;cursor:pointer;
  perspective:1100px;touch-action:none;-webkit-tap-highlight-color:transparent;
  --rx:0deg;--ry:0deg;--px:0;--py:0;--lift:0}
/* the warm light the card sits in. Everything that moves below moves by transform alone:
   sliding a gradient's position would repaint the whole card on every frame, which is what
   made the old card cost more than it looked like it should. */
.hc__aura{position:absolute;inset:-18% -16%;z-index:0;pointer-events:none;opacity:calc(.62 + var(--lift) * .38);
  background:radial-gradient(54% 44% at 50% 44%,rgba(230,176,110,.4),rgba(154,98,74,.14) 44%,transparent 70%)}
.hc__in{position:absolute;inset:0;z-index:1;transform-style:preserve-3d;transform:rotateX(var(--rx)) rotateY(var(--ry));transition:transform .85s cubic-bezier(.16,1,.3,1)}
.hc.flip .hc__in{transform:rotateX(var(--rx)) rotateY(calc(180deg + var(--ry)))}
.hc.live .hc__in{transition:transform .5s cubic-bezier(.16,1,.3,1)}
.hc__face{position:absolute;inset:0;border-radius:4.2%/3%;overflow:hidden;isolation:isolate;backface-visibility:hidden;-webkit-backface-visibility:hidden;
  box-shadow:0 34px 70px -26px rgba(0,0,0,.9),0 4px 14px -6px rgba(0,0,0,.55)}
.hc__back{transform:rotateY(180deg)}
.hc__plate,.hc__backimg{position:absolute;inset:0;display:block;width:100%;height:100%}
/* the portrait window: two layers drifting at different speeds, which is what reads as depth */
.hc__win{position:absolute;left:8.41%;top:14.8%;width:83.18%;height:36.4%;overflow:hidden}
.hc__win img{position:absolute;left:-8%;top:-8%;width:116%;height:116%;display:block}
.hc__bg{transform:translate3d(calc(var(--px) * 4.4%),calc(var(--py) * 4.4%),0) scale(1.015)}
.hc__sub{transform:translate3d(calc(var(--px) * 1.7%),calc(var(--py) * 1.7%),0)}
.hc__wsh{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 22px rgba(0,0,0,.45);mix-blend-mode:soft-light;
  background:linear-gradient(100deg,rgba(255,236,206,.16),transparent 42%)}
/* the foil, the gilt and the specular: each is a window with an oversized sheet inside it,
   and only the sheet moves, so a frame costs a transform rather than a repaint */
.hc__foil,.hc__sheen,.hc__glare{position:absolute;inset:0;pointer-events:none;overflow:hidden}
.hc__foil::before,.hc__sheen::before,.hc__glare::before{content:'';position:absolute;display:block}
.hc__foil{mix-blend-mode:color-dodge;opacity:calc(.2 + var(--lift) * .22);
  -webkit-mask-image:url(card/body.webp);mask-image:url(card/body.webp);-webkit-mask-size:100% 100%;mask-size:100% 100%}
.hc__foil::before{inset:-12% -80%;transform:translate3d(calc(var(--px) * -22%),0,0);
  background:linear-gradient(112deg,transparent 28%,rgba(255,104,170,.4) 40%,rgba(255,214,120,.46) 48%,rgba(120,226,255,.4) 56%,transparent 68%)}
.hc__back .hc__foil{-webkit-mask-image:none;mask-image:none;mix-blend-mode:screen;opacity:calc(.2 + var(--lift) * .22)}
.hc__back .hc__foil::before{background:linear-gradient(108deg,transparent 30%,rgba(196,142,86,.3) 43%,rgba(255,221,166,.42) 50%,rgba(178,134,92,.3) 57%,transparent 70%)}
/* the gilt: only the gold and cream catch this one, through a mask cut from the card itself */
.hc__sheen{mix-blend-mode:screen;opacity:calc(.34 + var(--lift) * .34);
  -webkit-mask-image:url(card/sheen.webp);mask-image:url(card/sheen.webp);-webkit-mask-size:100% 100%;mask-size:100% 100%}
.hc__sheen::before{inset:0 -100%;transform:translate3d(calc(var(--px) * 26%),0,0);
  background:linear-gradient(100deg,transparent 41%,rgba(255,243,212,1) 49%,rgba(255,224,164,.42) 55%,transparent 62%)}
.hc__glare{mix-blend-mode:soft-light}
.hc__glare::before{inset:-50%;transform:translate3d(calc(var(--px) * 23%),calc(var(--py) * 21%),0);
  background:radial-gradient(21% 16% at 50% 44%,rgba(255,251,238,.55),rgba(255,248,230,.12) 44%,transparent 72%)}
.hc__rim{position:absolute;inset:0;pointer-events:none;border-radius:inherit;
  box-shadow:inset 0 0 0 1px rgba(255,226,170,.3),inset 0 0 26px -6px rgba(0,0,0,.55);
  background:linear-gradient(102deg,rgba(0,0,0,.22),transparent 34%,transparent 66%,rgba(0,0,0,.26))}
.hc__hint{font:500 .6875rem/1 ui-monospace,'SF Mono',Menlo,Consolas,monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(232,228,224,.6)}
.hc__ht{display:none}
@media (hover:none){.hc__hm{display:none}.hc__ht{display:inline}}
@media (prefers-reduced-motion:reduce){.hl__shine{animation:none}.hc__in{transition:transform .4s ease}}
.holo__x{position:absolute;top:max(1rem,env(safe-area-inset-top));right:max(1rem,env(safe-area-inset-right));z-index:2;display:inline-flex;align-items:center;gap:.5rem;min-height:44px;padding:0 1rem;
  border-radius:999px;border:1px solid rgba(255,255,255,.2);background:rgba(20,18,18,.6);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);color:#F3EEEC;font:600 .8125rem/1 'Onest',ui-sans-serif,system-ui,sans-serif;cursor:pointer}
.holo__x:hover{background:rgba(40,36,36,.8)}
.holo__x svg{width:1rem;height:1rem}
.fig img,.fig canvas{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:50% 100%}
.fig canvas{pointer-events:none}

.hero__content{position:relative;z-index:20;display:flex;flex-direction:column;gap:2rem;padding-top:7rem;padding-bottom:calc(var(--fig-h) + 1.25rem)}
@media (min-width:1024px){
  .hero__content{display:grid;min-height:calc(100lvh - var(--bar-h));grid-template-columns:repeat(12,1fr);align-content:center;gap:2.5rem;padding-top:7rem;padding-bottom:4rem}
}
.hero__left{display:flex;flex-direction:column;gap:1.75rem;min-width:0}
.hero__right{display:flex;flex-direction:column;align-items:flex-start;gap:2rem;min-width:0}
@media (min-width:1024px){
  .hero__left{grid-column:1 / span 7}
  .hero__right{grid-column:1 / span 7;grid-row:2;align-self:end;flex-direction:row;align-items:flex-end;gap:2.25rem}
}

.eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-size:.875rem;font-weight:500;color:rgba(var(--fg-rgb),.7)}
.eyebrow::before{content:"";width:.375rem;height:.375rem;border-radius:9999px;background:rgba(var(--fg-rgb),.5)}
.h1{font-size:2.625rem;font-weight:600;line-height:.98;letter-spacing:-.02em;text-wrap:balance}
@media (min-width:640px){.h1{font-size:3.5rem}}
@media (min-width:768px){.h1{font-size:4.25rem}}
@media (min-width:1024px){.h1{font-size:4.75rem}}
@media (min-width:640px) and (max-width:1023.98px){.hero__left{padding-left:1.5rem}}
.h1 .soft{color:rgba(var(--fg-rgb),.5)}

/* ---------- flip calendar (skills) ---------- */
.cal-line{display:block;padding-top:.34em;margin-top:.1em;padding-bottom:.42em}
.cal{--cal-w:7em;position:relative;display:inline-block;font-size:.9em;perspective:14em;perspective-origin:30% 0;vertical-align:top;
  --from:translateY(.5em) rotateX(-18deg);--ease:var(--e-soft)}
.cal.rv{transition-duration:1.1s}
.cal__body{position:relative;display:block;width:var(--cal-w);height:1.72em;transform:rotateX(10deg) rotateY(-9deg);transform-style:preserve-3d;transition:width .5s var(--e-soft)}
.cal__stand{position:absolute;left:.2em;right:-.14em;top:.28em;bottom:-.4em;border-radius:.26em;
  background:linear-gradient(165deg,#3a3a3a 0%,#141414 40%,#050505 100%);
  box-shadow:0 .5em .9em -.35em rgba(0,0,0,.55),inset 0 .02em 0 rgba(255,255,255,.12);transform:translateZ(-.12em)}
.cal__stack{position:absolute;inset:0;transform-style:preserve-3d}
.cal__page,.cal__face,.cal__rear{position:absolute;inset:0;border-radius:.2em}
.cal__page{background:linear-gradient(180deg,#fbfaf7 0%,#f2f0eb 100%);
  box-shadow:0 .045em 0 #d8d4cb,0 .08em 0 #f6f4ef,0 .115em 0 #d0cbc1,0 .15em 0 #f2f0ea,0 .185em 0 #c8c3b8,0 .22em 0 #e9e6df,0 .255em 0 #aaa498,0 .45em .6em -.2em rgba(0,0,0,.35)}
.cal__leaf{position:absolute;inset:0;transform-origin:50% 0;transform-style:preserve-3d;transform:translateZ(.004em)}
.cal__face{background:linear-gradient(180deg,#fdfcf9 0%,#f3f1ec 100%);backface-visibility:hidden;-webkit-backface-visibility:hidden;box-shadow:inset 0 -.015em 0 rgba(0,0,0,.06)}
.cal__back{position:absolute;inset:0;border-radius:.2em;transform-origin:50% 0;transform:translateZ(-.004em) rotateX(352deg) translateY(50%) rotateX(180deg) translateY(-50%);backface-visibility:hidden;-webkit-backface-visibility:hidden;background:linear-gradient(0deg,#e9e6df 0%,#d9d5cc 100%);filter:brightness(.86)}
.cal__rear{background:linear-gradient(0deg,#e9e6df 0%,#d9d5cc 100%);transform:rotateX(180deg);backface-visibility:hidden;-webkit-backface-visibility:hidden}
.cal__word{position:absolute;inset:0;display:flex;align-items:center;padding:.2em .4em 0;color:#0a0a0a;font-weight:700;letter-spacing:-.035em;line-height:1;white-space:nowrap}
.cal__no{position:absolute;right:.42em;bottom:.2em;font-size:.15em;font-weight:500;letter-spacing:.08em;color:rgba(10,10,10,.42);font-variant-numeric:tabular-nums}
.cal__holes{position:absolute;top:.09em;left:.32em;right:.32em;height:.07em;display:flex;justify-content:space-between}
.cal__holes i{display:block;width:.075em;height:.075em;border-radius:50%;background:#1b1b1b;box-shadow:inset 0 .01em .01em rgba(255,255,255,.3)}
.cal__shade{position:absolute;inset:0;border-radius:inherit;pointer-events:none;opacity:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;background:linear-gradient(180deg,rgba(0,0,0,.5) 0%,rgba(0,0,0,.08) 70%,rgba(0,0,0,0) 100%)}
.cal__rings{position:absolute;top:-.27em;left:.32em;right:.32em;height:.42em;display:flex;justify-content:space-between;transform:translateZ(.05em);pointer-events:none}
.cal__rings i{display:block;width:.075em;height:.42em;position:relative}
.cal__rings i::before{content:"";position:absolute;left:-.065em;right:-.065em;top:0;bottom:0;border-radius:.2em;
  border:.04em solid #a9a9a9;border-left-color:#ededed;border-top-color:#f6f6f6;border-right-color:#6f6f6f;border-bottom-color:#8a8a8a;
  filter:drop-shadow(.01em .025em .015em rgba(0,0,0,.35))}
.cal__measure{position:absolute;visibility:hidden;white-space:nowrap;font-weight:700;letter-spacing:-.035em;pointer-events:none}

.rating{display:flex;align-items:center;gap:.75rem}
.stars{display:flex;gap:.1rem;color:var(--accent);font-size:1rem}
.rating p{font-size:.875rem;font-weight:500;color:rgba(var(--fg-rgb),.7)}
.ctas{display:flex;flex-wrap:wrap;gap:.75rem}

/* pill button */
.pill{display:inline-block;border-radius:9999px}
.pill__in{display:inline-flex;align-items:center;gap:.75rem;border-radius:9999px;font-size:.875rem;font-weight:500;padding:.875rem 1.75rem;white-space:nowrap}
.pill--arrow .pill__in{padding:.375rem .375rem .375rem 1.5rem}
.pill--dark .pill__in{background:var(--btn-bg);color:var(--btn-fg)}
.pill--light .pill__in{background:var(--surface);color:var(--foreground)}
.pill--outline .pill__in{border:1px solid var(--line);background:transparent;color:var(--foreground)}
.pill--outline:hover .pill__in{background:var(--outline-h)}
.pill__badge{width:2.25rem;height:2.25rem;display:grid;place-items:center;border-radius:9999px;font-size:1rem;background:var(--ink);color:#fff}
.pill--dark .pill__badge{background:var(--btn-badge-bg);color:var(--btn-badge-fg)}

/* hero card */
.hcard{width:100%;max-width:24rem;border-radius:var(--radius-card-sm);background:rgba(255,255,255,.7);padding:.5rem;
  box-shadow:0 0 0 1px rgba(230,229,226,.7),0 1px 2px rgba(0,0,0,.05);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);
  --from:translateY(16px) scale(.96);--d:400ms;--ease:var(--e-soft)}
@media (min-width:1024px){.hcard{width:19rem}}
.hcard__row{display:flex;gap:.5rem;cursor:pointer;border-radius:var(--radius-control)}
.hcard__tile{aspect-ratio:1;width:6rem;flex:none;display:grid;place-items:center;border-radius:var(--radius-control);background:var(--ink);font-size:1.875rem;color:var(--accent-from)}
.hcard__panel{flex:1;min-width:0;border-radius:var(--radius-control);background:rgba(241,240,238,.7);padding:.75rem;display:flex;flex-direction:column;justify-content:space-between;gap:.5rem}
.slot{position:relative;min-height:3.25rem}
.slide{position:absolute;inset:0;transition:transform .5s var(--e-snap),opacity .4s var(--e-snap)}
.slide__cap{font-size:.65rem;font-weight:500;text-transform:uppercase;letter-spacing:.05em;color:rgba(var(--fg-rgb),.45)}
.slide__ttl{max-width:8rem;margin-top:.15rem;font-size:.875rem;font-weight:500;line-height:1.35}
.hcard__ctrl{display:flex;align-items:center;justify-content:space-between}
.dots{display:flex;align-items:center;gap:.25rem}
.dots i{display:block;height:.25rem;width:.375rem;border-radius:9999px;background:rgba(var(--fg-rgb),.2);transition:all .3s}
.dots i.on{width:1rem;background:rgba(var(--fg-rgb),.7)}
.arrows{display:flex;gap:.25rem}
.rnd{width:1.75rem;height:1.75rem;display:grid;place-items:center;border-radius:9999px;background:#fff;color:rgba(var(--fg-rgb),.7);box-shadow:0 0 0 1px var(--line);font-size:.8rem;transition:color .2s}
.rnd:hover{color:var(--foreground)}
.rnd--prev svg{transform:rotate(180deg)}

/* partners */
.partners{width:100%;max-width:24rem;--from:translateY(14px);--d:550ms}
@media (min-width:1024px){.partners{width:auto;max-width:none}.partners ul{grid-template-columns:repeat(4,auto);justify-content:start;column-gap:1rem}}
.partners__lbl{margin-bottom:.75rem;font-size:.75rem;font-weight:500;color:rgba(var(--fg-rgb),.45);text-align:left}
.partners ul{display:grid;grid-template-columns:repeat(4,1fr);column-gap:1rem;row-gap:.75rem}
.partners li>span{display:flex;align-items:center;gap:.375rem;font-size:.75rem;color:rgba(var(--fg-rgb),.7);opacity:.7}
.partners li svg{font-size:.875rem;color:rgba(var(--fg-rgb),.4)}

/* status bar */
